/* Study OS — original multiple-choice practice for Principles of Economics (macro topics of the final).
   Written for Study OS to match the topics of the course practice sets (GDP, business cycle & unemployment,
   inflation, AD–AS, fiscal policy). No question text is copied from the course sets; numbers are invented.
   opts[0] is the correct answer. ids are stable: never renumber (answers are saved by id). */
window.ECO_PRACTICE_MCQ=[
// ---------- Measuring a nation's output (cat g) ----------
{id:"ep-g1",cat:"g",q:"GDP is the",opts:["market value of all final goods and services produced within a country in a period","number of goods produced by a country's citizens anywhere in the world","market value of all goods sold in a country, new or used","total income earned by a country's citizens, including transfers"],exp:"GDP counts final goods and services, at market value, produced inside the country's borders during the period."},
{id:"ep-g2",cat:"g",q:"Which purchase is counted in this year's GDP?",opts:["A haircut bought this year","Shares of a listed company","A second-hand motorbike","Unpaid cooking at home"],exp:"Financial assets, used goods and non-market work are not new production."},
{id:"ep-g3",cat:"g",q:"Which item is NOT included in GDP?",opts:["An antique table made in 1960 and resold this year","A new phone bought by a household","A concert ticket bought this year","A new factory machine bought by a firm"],exp:"The antique was counted when it was produced; reselling it creates no new output."},
{id:"ep-g4",cat:"g",q:"GDP includes",opts:["only final goods and services","intermediate and final goods","used goods resold during the year","imports bought by households"],exp:"Counting intermediate goods would count the same value twice."},
{id:"ep-g5",cat:"g",q:"Using the expenditure approach, GDP equals",opts:["C + I + G + (X − M)","C + I + G + (X + M)","C + I − G + (X − M)","C + G + X"],exp:"Consumption + gross private domestic investment + government purchases + net exports."},
{id:"ep-g6",cat:"g",q:"Government spending (G) in the GDP equation excludes",opts:["transfer payments such as pensions and unemployment benefits","road construction","salaries of public school teachers","military equipment"],exp:"Transfers move income without buying newly produced goods or services."},
{id:"ep-g7",cat:"g",q:"Which is a final good?",opts:["Paint bought by a homeowner to repaint her house","Paint bought by a car maker for new cars","Flour bought by a bakery","Steel bought by a shipyard"],exp:"Goods bought by the final user count; goods used up in producing other goods are intermediate."},
{id:"ep-g8",cat:"g",q:"In the circular flow model, households spend money on goods and services in the",opts:["product markets","factor markets","financial markets only","government sector only"],exp:"Firms sell output in product markets; households sell labour and other resources in factor markets."},
{id:"ep-g9",cat:"g",q:"Which is a limitation of GDP as a measure of well-being?",opts:["It leaves out non-market activities such as housework","It includes investment spending","It counts services as well as goods","It is measured in money"],exp:"GDP also ignores leisure, the underground economy and environmental damage."},
{id:"ep-g10",cat:"g",q:"If a country has a large underground economy, its official GDP",opts:["understates the true level of production","overstates the true level of production","measures production exactly","includes those activities at double their value"],exp:"Unreported market activity is missing from official GDP."},
{id:"ep-g11",cat:"g",q:"Real GDP for a year equals",opts:["nominal GDP ÷ GDP deflator × 100","nominal GDP × GDP deflator × 100","nominal GDP − GDP deflator","nominal GDP ÷ population"],exp:"Dividing by the price index removes the effect of price changes."},
{id:"ep-g12",cat:"g",q:"If output stays the same but all prices rise by 5%, then",opts:["nominal GDP rises but real GDP does not","real GDP rises by 5%","both nominal and real GDP fall","neither nominal nor real GDP changes"],exp:"Nominal GDP is in current prices; real GDP holds prices constant."},
{id:"ep-g13",cat:"g",q:"A tailor buys cloth for $120 and buttons for $30, and sells finished shirts for $600. How much do the shirts add to GDP?",opts:["$600","$750","$450","$150"],exp:"Only the final good's value counts: $600 (equal to the sum of value added at each stage)."},
{id:"ep-g14",cat:"g",q:"Using the value-added approach for the tailor (inputs $150, sales $600), how much value did the tailor add?",opts:["$450","$600","$150","$750"],exp:"Value added = sales − purchased inputs = 600 − 150."},
{id:"ep-g15",cat:"g",q:"Nominal GDP rose from one year to the next. What can you conclude about real output?",opts:["Not enough information — prices may have risen","It must have risen","It must have fallen","It stayed the same"],exp:"Higher nominal GDP can come from higher prices, more output, or both."},
{id:"ep-g16",cat:"g",q:"The baht moves from 33 THB/USD to 35 THB/USD. What happens?",opts:["The baht depreciates: Thai exports become cheaper to foreigners and imports dearer","The baht appreciates: Thai imports become cheaper","Both Thai exports and imports become cheaper","Nothing changes for trade"],exp:"More baht are needed for one dollar, so the baht has lost value."},
{id:"ep-g17",cat:"g",q:"The baht appreciates from 34 to 32 THB/USD. Who gains most?",opts:["Thai importers","Thai exporters","Foreign tourists visiting Thailand","Thai firms selling abroad"],exp:"Each dollar of imports now costs fewer baht."},
{id:"ep-g18",cat:"g",case:"An economy produces only rice and fish (base year 2023).\n| Year | Rice price | Rice qty | Fish price | Fish qty |\n|---|---|---|---|---|\n| 2023 | $2 | 100 | $5 | 40 |\n| 2024 | $3 | 120 | $6 | 50 |",q:"What is nominal GDP in 2024?",opts:["$660","$490","$400","$540"],exp:"3 × 120 + 6 × 50 = 360 + 300 = 660."},
{id:"ep-g19",cat:"g",case:"An economy produces only rice and fish (base year 2023).\n| Year | Rice price | Rice qty | Fish price | Fish qty |\n|---|---|---|---|---|\n| 2023 | $2 | 100 | $5 | 40 |\n| 2024 | $3 | 120 | $6 | 50 |",q:"What is real GDP in 2024 (2023 prices)?",opts:["$490","$660","$400","$560"],exp:"2 × 120 + 5 × 50 = 240 + 250 = 490."},
{id:"ep-g20",cat:"g",case:"An economy produces only rice and fish (base year 2023).\n| Year | Rice price | Rice qty | Fish price | Fish qty |\n|---|---|---|---|---|\n| 2023 | $2 | 100 | $5 | 40 |\n| 2024 | $3 | 120 | $6 | 50 |",q:"What is the GDP deflator for 2024?",opts:["About 134.7","100","74.2","122.5"],exp:"Nominal ÷ real × 100 = 660 ÷ 490 × 100 ≈ 134.7. In the base year the deflator is 100."},
// ---------- Business cycle and unemployment (cat b) ----------
{id:"ep-b1",cat:"b",q:"Economic growth is best measured by an increase in",opts:["real GDP","nominal GDP","the price level","the labour force"],exp:"Real GDP removes the effect of price changes."},
{id:"ep-b2",cat:"b",q:"The phase of the business cycle from a trough to the next peak is called",opts:["expansion (recovery)","recession","contraction","depression"],exp:"Real GDP rises from the trough until it reaches a peak."},
{id:"ep-b3",cat:"b",q:"During a recovery phase, we would most likely see",opts:["falling unemployment and rising output","rising unemployment and falling output","falling output and falling prices","no change in output"],exp:"Firms produce more and hire more workers."},
{id:"ep-b4",cat:"b",q:"A recession is commonly defined as",opts:["a fall in real GDP for at least two quarters in a row","any rise in unemployment","a fall in the price level","a year of slow growth in nominal GDP"],exp:"This is the usual rule of thumb."},
{id:"ep-b5",cat:"b",q:"Which person is counted as unemployed?",opts:["Somchai, laid off last month and applying for jobs every week","Dao, a full-time student not looking for work","Niran, retired at 65","Mali, who stopped looking because she thinks there are no jobs"],exp:"Unemployed people are without work but actively looking. Mali is a discouraged worker, outside the labour force."},
{id:"ep-b6",cat:"b",q:"The civilian labour force is",opts:["the employed plus the unemployed","the employed only","everyone aged 16 and over","the unemployed plus discouraged workers"],exp:"Labour force = employed + unemployed (people working or looking for work)."},
{id:"ep-b7",cat:"b",q:"Discouraged workers cause the official unemployment rate to",opts:["understate true unemployment","overstate true unemployment","be exactly right","rise above 100%"],exp:"They want jobs but are not counted, because they have stopped looking."},
{id:"ep-b8",cat:"b",q:"Employed 47 million, unemployed 3 million. What is the unemployment rate?",opts:["6%","6.4%","3%","5%"],exp:"3 ÷ (47 + 3) = 3 ÷ 50 = 6%."},
{id:"ep-b9",cat:"b",q:"Frictional unemployment 2 million, structural 3 million, cyclical 1 million, employed 94 million. What is the labour force?",opts:["100 million","94 million","97 million","106 million"],exp:"Unemployed 6 + employed 94 = 100 million."},
{id:"ep-b10",cat:"b",q:"Using the same data (labour force 100 million, cyclical 1 million), what is the natural rate of unemployment?",opts:["5%","6%","1%","3%"],exp:"Natural rate = frictional + structural = (2 + 3) ÷ 100 = 5%."},
{id:"ep-b11",cat:"b",q:"Short-term unemployment while people move between jobs or enter the labour force is",opts:["frictional unemployment","structural unemployment","cyclical unemployment","seasonal unemployment"],exp:"It reflects the time needed to search for a job."},
{id:"ep-b12",cat:"b",q:"Structural unemployment is caused by",opts:["a mismatch between workers' skills or location and the jobs available","a recession","workers changing jobs voluntarily","bad weather"],exp:"For example, new technology replacing a type of job."},
{id:"ep-b13",cat:"b",q:"A new graduate searching for her first job is an example of",opts:["frictional unemployment","structural unemployment","cyclical unemployment","underemployment"],exp:"She is in the job-search process."},
{id:"ep-b14",cat:"b",q:"Arthit lost his job because sales fell during a recession. This is",opts:["cyclical unemployment","frictional unemployment","structural unemployment","seasonal unemployment"],exp:"Cyclical unemployment comes from a fall in aggregate demand."},
{id:"ep-b15",cat:"b",q:"Film-camera factory workers lose their jobs as people switch to phone cameras. This is",opts:["structural unemployment","cyclical unemployment","frictional unemployment","seasonal unemployment"],exp:"Demand for that skill has disappeared permanently."},
{id:"ep-b16",cat:"b",q:"Full employment means",opts:["there is no cyclical unemployment","the unemployment rate is zero","there is no frictional unemployment","everyone over 16 has a job"],exp:"Frictional and structural unemployment still exist at the natural rate."},
{id:"ep-b17",cat:"b",q:"If the actual unemployment rate is above the natural rate, the economy is",opts:["producing below potential real GDP (a recessionary gap)","producing above potential real GDP","at full employment","experiencing hyperinflation"],exp:"Cyclical unemployment exists, so output is below potential."},
{id:"ep-b18",cat:"b",q:"The working-age population is 80 million and the labour force is 52 million. What is the labour force participation rate?",opts:["65%","52%","35%","154%"],exp:"52 ÷ 80 = 65%."},
// ---------- Inflation (cat i) ----------
{id:"ep-i1",cat:"i",q:"Inflation is",opts:["a rise in the general price level","a rise in the price of one good","a rise in real GDP","a rise in the money wage of one industry"],exp:"It is a sustained increase in the average level of prices."},
{id:"ep-i2",cat:"i",q:"The base year of a price index is",opts:["the year whose prices are used for comparison and whose index equals 100","the year with the lowest prices","always the current year","the year with the highest inflation"],exp:"Other years are measured relative to it."},
{id:"ep-i3",cat:"i",q:"The CPI rises from 200 to 215. What is the inflation rate?",opts:["7.5%","15%","1.5%","8.5%"],exp:"(215 − 200) ÷ 200 = 7.5%."},
{id:"ep-i4",cat:"i",q:"The CPI was 120 last year and 126 this year. The inflation rate is",opts:["5%","6%","26%","4.8%"],exp:"(126 − 120) ÷ 120 = 5%."},
{id:"ep-i5",cat:"i",q:"When the price of mangoes rises, consumers buy more bananas instead, but the CPI basket is fixed. As a result the CPI",opts:["overstates the rise in the cost of living (substitution bias)","understates the rise in the cost of living","measures it exactly","falls"],exp:"A fixed basket ignores switching to cheaper goods."},
{id:"ep-i6",cat:"i",q:"Deflation is",opts:["a fall in the general price level","a fall in the inflation rate","a fall in real GDP","a fall in the money supply only"],exp:"A lower but still positive inflation rate is disinflation, not deflation."},
{id:"ep-i7",cat:"i",q:"Real income equals",opts:["nominal income ÷ CPI × 100","nominal income × CPI","nominal income − CPI","CPI ÷ nominal income"],exp:"It measures purchasing power in base-year prices."},
{id:"ep-i8",cat:"i",q:"Your salary rises 4% while prices rise 6%. Your real income",opts:["falls about 2%","rises about 2%","rises 10%","is unchanged"],exp:"Real change ≈ nominal change − inflation."},
{id:"ep-i9",cat:"i",q:"Demand-pull inflation is caused by",opts:["aggregate demand rising faster than the economy can produce","higher oil prices","higher wages forced by unions","a fall in productivity"],exp:"'Too much spending chasing too few goods.'"},
{id:"ep-i10",cat:"i",q:"Cost-push inflation is caused by",opts:["higher production costs that shift aggregate supply left","higher consumer spending","lower interest rates","more government spending"],exp:"Examples: higher oil or wage costs."},
{id:"ep-i11",cat:"i",q:"During hyperinflation, people are most likely to",opts:["spend money as quickly as possible","save more cash","lend money at fixed interest","keep prices fixed"],exp:"Money loses value rapidly, so holding it is costly."},
{id:"ep-i12",cat:"i",q:"Who is hurt by unexpected inflation?",opts:["Lenders at a fixed interest rate","Borrowers at a fixed interest rate","People whose income rises faster than prices","Owners of assets whose value rises with prices"],exp:"They are repaid in money worth less than expected."},
{id:"ep-i13",cat:"i",q:"A nominal interest rate is 7% and inflation is 3%. The real interest rate is about",opts:["4%","10%","2.3%","21%"],exp:"Real ≈ nominal − inflation."},
{id:"ep-i14",cat:"i",q:"A ticket cost $0.40 when the CPI was 20. The CPI is now 260. In today's dollars, the ticket cost",opts:["$5.20","$3.25","$0.40","$104"],exp:"0.40 × 260 ÷ 20 = 5.20."},
{id:"ep-i15",cat:"i",q:"A basket costs $500 in the base year and $560 this year. What is this year's price index?",opts:["112","60","89","560"],exp:"560 ÷ 500 × 100 = 112."},
// ---------- Aggregate demand and aggregate supply (cat a) ----------
{id:"ep-a1",cat:"a",q:"The aggregate demand curve shows the relationship between",opts:["the price level and the real GDP demanded","interest rates and investment","the price of one good and its quantity","wages and employment"],exp:"It slopes downward: a lower price level raises real GDP demanded."},
{id:"ep-a2",cat:"a",q:"Which is NOT a component of aggregate demand?",opts:["Intermediate goods purchases","Consumption","Investment","Net exports"],exp:"AD = C + I + G + (X − M)."},
{id:"ep-a3",cat:"a",q:"The real balances (wealth) effect says a higher price level",opts:["reduces the purchasing power of people's money and other financial assets, so they spend less","raises the real value of savings","has no effect on spending","increases exports"],exp:"This is one reason the AD curve slopes downward."},
{id:"ep-a4",cat:"a",q:"Which shifts aggregate demand to the LEFT?",opts:["Consumers become pessimistic and save more","Government increases spending","Foreign incomes rise, raising exports","Firms become optimistic and invest more"],exp:"Lower consumption reduces AD at every price level."},
{id:"ep-a5",cat:"a",q:"A large rise in world oil prices shifts",opts:["aggregate supply to the left","aggregate supply to the right","aggregate demand to the right","neither curve"],exp:"Higher input costs reduce output at each price level."},
{id:"ep-a6",cat:"a",q:"Stagflation is",opts:["rising unemployment together with rising inflation","falling unemployment with falling prices","rapid growth with low inflation","a fall in the money supply"],exp:"It typically follows a leftward shift of aggregate supply."},
{id:"ep-a7",cat:"a",q:"An increase in aggregate supply (shift right) could be caused by",opts:["new technology that raises productivity","higher oil prices","higher business taxes on output","a drought"],exp:"Lower costs or more resources raise output at each price level."},
{id:"ep-a8",cat:"a",q:"In the Keynesian (horizontal) range of the AS curve, an increase in AD",opts:["raises real GDP without raising the price level","raises only the price level","lowers real GDP","has no effect"],exp:"There are many idle resources."},
{id:"ep-a9",cat:"a",q:"In the classical (vertical) range of the AS curve, an increase in AD",opts:["raises only the price level","raises only real GDP","raises both equally","lowers the price level"],exp:"The economy is already at full employment."},
{id:"ep-a10",cat:"a",q:"In the intermediate range of the AS curve, an increase in AD causes",opts:["both real GDP and the price level to rise","only the price level to rise","only real GDP to rise","both to fall"],exp:"Some resources become scarce, so prices start to rise."},
{id:"ep-a11",cat:"a",q:"Classical economists believe that",opts:["prices and wages are flexible, so the economy returns to full employment on its own","the government must always manage demand","prices are fixed in the short run","unemployment cannot fall"],exp:"Keynesians argue prices and wages are sticky, especially downward."},
{id:"ep-a12",cat:"a",q:"If equilibrium real GDP is below full-employment GDP, the economy has",opts:["a recessionary gap","an inflationary gap","no gap","stagflation by definition"],exp:"Output is below potential and cyclical unemployment exists."},
{id:"ep-a13",cat:"a",q:"If AD shifts right while the economy is already at full employment, the result is",opts:["demand-pull inflation","cost-push inflation","deflation","a recession"],exp:"Output cannot rise much, so prices rise."},
{id:"ep-a14",cat:"a",q:"A fall in aggregate demand in the intermediate range of AS leads to",opts:["lower real GDP and a lower price level","higher real GDP and lower prices","lower real GDP and higher prices","no change"],exp:"Both output and the price level fall."},
{id:"ep-a15",cat:"a",q:"Which would shift aggregate demand to the right?",opts:["A depreciation of the baht that raises net exports","Higher taxes on households","A fall in business confidence","A rise in the price level"],exp:"A change in the price level is a movement along AD, not a shift."},
// ---------- Fiscal policy (cat f) ----------
{id:"ep-f1",cat:"f",q:"Which is an example of expansionary fiscal policy?",opts:["Cutting income taxes","Raising income taxes","Reducing government purchases","Raising the policy interest rate"],exp:"Fiscal policy uses government spending and taxes; interest rates are monetary policy."},
{id:"ep-f2",cat:"f",q:"Contractionary fiscal policy is used to",opts:["reduce inflation by lowering aggregate demand","end a recession","raise unemployment benefits","increase the money supply"],exp:"It cuts spending or raises taxes."},
{id:"ep-f3",cat:"f",q:"The spending multiplier equals",opts:["1 ÷ (1 − MPC)","MPC ÷ (1 − MPC)","1 − MPC","1 ÷ MPC"],exp:"With MPC = 0.8 it is 5."},
{id:"ep-f4",cat:"f",q:"The tax multiplier equals",opts:["−MPC ÷ (1 − MPC)","1 ÷ (1 − MPC)","−1 ÷ MPC","MPC × (1 − MPC)"],exp:"It is smaller than the spending multiplier because part of a tax cut is saved."},
{id:"ep-f5",cat:"f",q:"MPC = 0.8. Government spending rises by $20 billion. By how much does aggregate demand shift (spending multiplier)?",opts:["$100 billion","$80 billion","$20 billion","$16 billion"],exp:"Multiplier 1 ÷ 0.2 = 5; 5 × 20 = 100."},
{id:"ep-f6",cat:"f",q:"MPC = 0.75. Taxes rise by $40 billion. What is the change in aggregate demand?",opts:["Decrease of $120 billion","Decrease of $160 billion","Increase of $120 billion","Decrease of $30 billion"],exp:"Tax multiplier −0.75 ÷ 0.25 = −3; −3 × 40 = −120."},
{id:"ep-f7",cat:"f",q:"MPC = 0.9. Real GDP is $50 billion below full employment (Keynesian range). How much extra government spending closes the gap?",opts:["$5 billion","$50 billion","$45 billion","$10 billion"],exp:"Multiplier 10; 50 ÷ 10 = 5."},
{id:"ep-f8",cat:"f",q:"MPC = 0.8. Government spending and taxes both rise by $10 billion. Aggregate demand rises by",opts:["$10 billion (balanced budget multiplier = 1)","$50 billion","$0","$40 billion"],exp:"Spending +50, taxes −40, net +10."},
{id:"ep-f9",cat:"f",q:"Automatic stabilizers in a recession",opts:["increase the budget deficit without new laws","require Parliament to pass new spending","raise tax revenue","reduce transfer payments"],exp:"Tax revenue falls and transfers rise automatically."},
{id:"ep-f10",cat:"f",q:"Unemployment benefits are an automatic stabilizer because they",opts:["rise during recessions, supporting spending","rise during booms","are set by the central bank","only change when taxes change"],exp:"They put money in people's hands when incomes fall."},
{id:"ep-f11",cat:"f",q:"Supply-side economists argue that cutting tax rates on wages and profits will",opts:["increase work, saving and investment, shifting aggregate supply right","shift aggregate supply left","only raise aggregate demand","raise inflation without raising output"],exp:"They focus on incentives to produce."},
{id:"ep-f12",cat:"f",q:"In the classical (vertical) range of AS, expansionary fiscal policy mainly",opts:["raises the price level","raises real GDP","lowers unemployment a lot","lowers prices"],exp:"Output is already at full employment."},
{id:"ep-f13",cat:"f",q:"In the Keynesian range of AS, expansionary fiscal policy",opts:["raises real GDP with little or no inflation","raises only prices","has no effect","lowers real GDP"],exp:"There are idle resources to put to work."},
{id:"ep-f14",cat:"f",q:"A budget deficit occurs when",opts:["government spending is greater than tax revenue","tax revenue is greater than spending","exports are greater than imports","the money supply grows"],exp:"The difference is usually borrowed."},
{id:"ep-f15",cat:"f",q:"The crowding-out effect means that government borrowing",opts:["raises interest rates and reduces private investment","increases private investment","lowers interest rates","has no effect on the private sector"],exp:"It weakens the effect of expansionary fiscal policy."},
// ---------- Growth & development (cat d), added 18 Nov 2026 ----------
{id:"ep-d1",cat:"d",q:"Economic growth is usually measured as the percentage increase in",opts:["real GDP per person", "nominal GDP", "the price level", "the money supply"],exp:"Growth in living standards is tracked by real GDP per person, which removes inflation and population growth."},
{id:"ep-d2",cat:"d",q:"Which factor most directly raises labour productivity?",opts:["More physical capital per worker", "A higher price level", "A larger budget deficit", "Higher import tariffs"],exp:"Workers produce more when each has more tools and machines to work with."},
{id:"ep-d3",cat:"d",q:"Human capital refers to",opts:["the knowledge and skills workers gain through education, training and experience", "machines and buildings used in production", "natural resources such as land and minerals", "money saved in banks"],exp:"Human capital is investment in people; physical capital is investment in equipment and structures."},
{id:"ep-d4",cat:"d",q:"Diminishing returns to capital means that as the capital stock rises,",opts:["each extra unit of capital adds less to output", "output falls", "each extra unit of capital adds more to output", "labour becomes less productive"],exp:"Extra machines help less and less when workers already have many."},
{id:"ep-d5",cat:"d",q:"The catch-up effect says that",opts:["poor countries tend to grow faster than rich ones, other things equal", "rich countries always grow faster than poor ones", "growth stops once a country is rich", "all countries grow at the same rate"],exp:"Because of diminishing returns, capital added in a poor country raises output more."},
{id:"ep-d6",cat:"d",q:"Technological knowledge is important for growth because it",opts:["raises output from the same inputs", "is used up when one firm uses it", "only matters in agriculture", "lowers the price level"],exp:"Better methods let the same labour and capital produce more."},
{id:"ep-d7",cat:"d",q:"A rise in a country's saving rate, other things equal, most likely leads to",opts:["more investment and faster growth for a time", "lower investment", "a permanent fall in output", "higher unemployment in the long run"],exp:"Saving funds investment; growth speeds up until diminishing returns set in."},
{id:"ep-d8",cat:"d",q:"Foreign direct investment is",opts:["capital investment owned and operated by a foreign firm", "a loan from the central bank", "buying foreign stocks only for short-term gain", "government spending abroad"],exp:"For example, a foreign carmaker building and running a factory in the country."},
{id:"ep-d9",cat:"d",q:"Which policy is LEAST likely to raise long-run growth?",opts:["Banning imports of new technology", "Improving schools", "Protecting property rights", "Encouraging saving and investment"],exp:"Blocking trade and new technology usually slows productivity growth."},
{id:"ep-d10",cat:"d",q:"Political stability and secure property rights help growth because they",opts:["make people willing to save and invest", "raise the price level", "reduce the need for capital", "lower the population"],exp:"Investors need confidence that they will keep the returns on what they build."},
{id:"ep-d11",cat:"d",q:"Fast population growth can lower income per person mainly by",opts:["spreading the capital stock over more workers", "raising the saving rate", "increasing the price of land only", "reducing unemployment"],exp:"With more workers, each has less capital to work with (capital dilution)."},
{id:"ep-d12",cat:"d",q:"Economic development differs from economic growth because development also includes",opts:["improvements in health, education and living conditions", "only a rise in real GDP", "only a rise in exports", "only a rise in prices"],exp:"Development looks at broader well-being, not just output."},
{id:"ep-d13",cat:"d",q:"The Human Development Index (HDI) combines",opts:["income, health (life expectancy) and education", "inflation, unemployment and interest rates", "exports, imports and tariffs", "saving, investment and taxes"],exp:"The HDI adds health and education to income per person."},
{id:"ep-d14",cat:"d",q:"Real GDP per person grows from 10,000 to 10,300 in a year. The growth rate is",opts:["3%", "30%", "0.3%", "300%"],exp:"(10,300 − 10,000) ÷ 10,000 = 0.03 = 3%."},
{id:"ep-d15",cat:"d",q:"By the rule of 70, an economy growing 2% a year doubles its income in about",opts:["35 years", "14 years", "70 years", "140 years"],exp:"Doubling time ≈ 70 ÷ growth rate = 70 ÷ 2 = 35 years."},
{id:"ep-d16",cat:"d",q:"By the rule of 70, an economy growing 7% a year doubles its income in about",opts:["10 years", "7 years", "49 years", "70 years"],exp:"70 ÷ 7 = 10 years."},
{id:"ep-d17",cat:"d",q:"Research and development (R&D) helps growth because new knowledge is largely a",opts:["public good that many firms can use", "private good used up by one firm", "type of natural resource", "form of money"],exp:"Once discovered, ideas can be used by many at little extra cost."},
{id:"ep-d18",cat:"d",q:"Natural resources such as land and minerals are",opts:["inputs to production that may be renewable or non-renewable", "the same as human capital", "always unlimited", "a type of money"],exp:"Oil is non-renewable; forests can be renewable if managed."},
{id:"ep-d19",cat:"d",q:"Which is an example of investment in physical capital?",opts:["A firm buys new machines for its factory", "A student pays university fees", "A family buys government bonds", "A worker takes a training course"],exp:"Machines are physical capital; schooling and training are human capital."},
{id:"ep-d20",cat:"d",q:"Outward-oriented trade policies tend to help growth because they",opts:["let countries specialise and gain new technology through trade", "stop all imports", "raise tariffs on machines", "keep foreign firms out"],exp:"Trade lets a country use its comparative advantage and learn from others."},
// ---------- Money & banking (cat m), added 18 Nov 2026 ----------
{id:"ep-m1",cat:"m",q:"The three functions of money are",opts:["medium of exchange, unit of account and store of value", "medium of exchange, tax collection and lending", "unit of account, inflation control and saving", "store of value, investment and spending"],exp:"Money is used to buy things, to measure prices and to hold wealth over time."},
{id:"ep-m2",cat:"m",q:"Using money to buy coffee is an example of money as a",opts:["medium of exchange", "unit of account", "store of value", "standard of deferred payment only"],exp:"A medium of exchange is what buyers give sellers for goods and services."},
{id:"ep-m3",cat:"m",q:"Prices posted in baht show money acting as a",opts:["unit of account", "medium of exchange", "store of value", "liquid asset"],exp:"A unit of account is the yardstick used to post prices and record debts."},
{id:"ep-m4",cat:"m",q:"Keeping cash in a drawer to spend next month uses money as a",opts:["store of value", "unit of account", "medium of exchange", "commodity"],exp:"A store of value carries purchasing power into the future."},
{id:"ep-m5",cat:"m",q:"Liquidity means",opts:["how easily an asset can be turned into the economy's medium of exchange", "how much interest an asset pays", "how risky an asset is", "how much an asset is worth"],exp:"Cash is the most liquid asset; a house is much less liquid."},
{id:"ep-m6",cat:"m",q:"Commodity money is",opts:["money that has value of its own, such as gold", "paper money with no value of its own", "money created by commercial banks", "a credit card"],exp:"Gold coins have intrinsic value; fiat money does not."},
{id:"ep-m7",cat:"m",q:"Fiat money is",opts:["money with no value of its own, used because the government declares it legal tender", "money backed by gold", "a commodity such as salt", "a bank loan"],exp:"Modern banknotes are fiat money."},
{id:"ep-m8",cat:"m",q:"Which is NOT counted as money (M1)?",opts:["A credit card limit", "Currency held by the public", "Demand (chequing) deposits", "Traveller's cheques"],exp:"A credit card is a way to borrow, not money itself."},
{id:"ep-m9",cat:"m",q:"M2 includes M1 plus",opts:["savings deposits, small time deposits and money market funds", "only coins", "government bonds", "the value of houses"],exp:"M2 adds less-liquid near-money assets to M1."},
{id:"ep-m10",cat:"m",q:"A central bank's main jobs include",opts:["controlling the money supply and supervising banks", "collecting income tax", "setting the government budget", "selling goods to the public"],exp:"The central bank (e.g. the Bank of Thailand) runs monetary policy and regulates banks."},
{id:"ep-m11",cat:"m",q:"In a fractional-reserve banking system, banks",opts:["keep only part of their deposits as reserves and lend the rest", "keep all deposits as reserves", "cannot make loans", "print their own currency"],exp:"Lending part of deposits is how banks create money."},
{id:"ep-m12",cat:"m",q:"If the reserve ratio is 10%, the money multiplier is",opts:["10", "0.1", "1", "100"],exp:"Money multiplier = 1 ÷ reserve ratio = 1 ÷ 0.10 = 10."},
{id:"ep-m13",cat:"m",q:"If the reserve ratio is 20%, the money multiplier is",opts:["5", "20", "0.2", "2"],exp:"1 ÷ 0.20 = 5."},
{id:"ep-m14",cat:"m",q:"With a 10% reserve ratio, a new 1,000-baht deposit of reserves (for example, from the central bank) can support total deposits in the banking system of at most",opts:["10,000 baht", "1,000 baht", "100 baht", "900 baht"],exp:"Total deposits = new reserves × money multiplier = 1,000 × (1 ÷ 0.10) = 10,000 baht."},
{id:"ep-m15",cat:"m",q:"A bank has deposits of 500,000 and a 10% reserve requirement. Its required reserves are",opts:["50,000", "5,000", "450,000", "500,000"],exp:"500,000 × 10% = 50,000; the rest can be lent."},
{id:"ep-m16",cat:"m",q:"Excess reserves are",opts:["reserves held above the required amount", "the reserves the law requires", "loans the bank has made", "the bank's capital"],exp:"Excess reserves = total reserves − required reserves."},
{id:"ep-m17",cat:"m",q:"When a bank makes a new loan by crediting the borrower's account, the money supply",opts:["rises", "falls", "stays the same", "becomes zero"],exp:"The new deposit is new money."},
{id:"ep-m18",cat:"m",q:"If people decide to hold more cash and fewer deposits, the money multiplier",opts:["falls", "rises", "does not change", "becomes infinite"],exp:"Cash outside banks cannot be lent out, so less money is created."},
{id:"ep-m19",cat:"m",q:"If banks choose to hold more excess reserves, the money supply",opts:["falls", "rises", "does not change", "doubles"],exp:"Banks lend less, so less money is created."},
{id:"ep-m20",cat:"m",q:"A bank's balance sheet lists deposits as",opts:["liabilities", "assets", "capital", "revenue"],exp:"The bank owes deposits to customers; loans and reserves are its assets."},
{id:"ep-m21",cat:"m",q:"Leverage in banking means",opts:["using borrowed money (deposits) to finance assets", "holding 100% reserves", "paying no interest", "printing money"],exp:"A leverage ratio = assets ÷ bank capital."},
{id:"ep-m22",cat:"m",q:"A bank run happens when",opts:["many depositors try to withdraw their money at once", "the central bank raises interest rates", "a bank pays high interest", "the government raises taxes"],exp:"With fractional reserves, a bank cannot pay everyone at once."},
{id:"ep-m23",cat:"m",q:"Deposit insurance helps prevent bank runs because",opts:["depositors know their money is safe even if the bank fails", "banks must hold 100% reserves", "it raises interest rates", "it stops banks from lending"],exp:"Safe depositors have no reason to rush to withdraw."},
{id:"ep-m24",cat:"m",q:"The quantity theory of money says that, in the long run, faster money growth mainly causes",opts:["higher inflation", "higher real GDP", "lower prices", "lower unemployment"],exp:"With MV = PY and Y set by real factors, more M means a higher P."},
{id:"ep-m25",cat:"m",q:"In the equation MV = PY, V stands for",opts:["the velocity of money", "the value of output", "the volume of trade", "the interest rate"],exp:"Velocity is how many times a unit of money is spent in a year."},
// ---------- Monetary policy (cat n), added 18 Nov 2026 ----------
{id:"ep-n1",cat:"n",q:"Monetary policy is decided by",opts:["the central bank", "the Ministry of Finance alone", "commercial banks", "parliament each month"],exp:"In Thailand the Bank of Thailand's Monetary Policy Committee sets policy."},
{id:"ep-n2",cat:"n",q:"Open-market operations are",opts:["the central bank buying or selling government bonds", "the government raising taxes", "banks lending to each other", "the central bank printing new notes for shops"],exp:"Buying bonds adds reserves to banks; selling bonds takes them away."},
{id:"ep-n3",cat:"n",q:"When the central bank buys government bonds from banks, the money supply",opts:["rises", "falls", "stays the same", "is cut in half"],exp:"Banks get new reserves they can lend."},
{id:"ep-n4",cat:"n",q:"When the central bank sells government bonds, interest rates tend to",opts:["rise", "fall", "stay at zero", "become negative"],exp:"Less money in the system pushes interest rates up."},
{id:"ep-n5",cat:"n",q:"Raising the reserve requirement will",opts:["reduce the money supply", "increase the money supply", "have no effect", "increase bank lending"],exp:"Banks must hold more and can lend less, so the multiplier falls."},
{id:"ep-n6",cat:"n",q:"Lowering the policy (discount) interest rate is an example of",opts:["expansionary monetary policy", "contractionary monetary policy", "fiscal policy", "a supply shock"],exp:"Cheaper borrowing encourages spending and investment."},
{id:"ep-n7",cat:"n",q:"Expansionary monetary policy shifts the aggregate demand curve",opts:["to the right", "to the left", "not at all", "only along the curve"],exp:"Lower interest rates raise investment and consumption."},
{id:"ep-n8",cat:"n",q:"To fight high inflation, the central bank would most likely",opts:["raise interest rates", "lower interest rates", "buy more government bonds", "lower the reserve requirement"],exp:"Tighter money reduces aggregate demand and price pressure."},
{id:"ep-n9",cat:"n",q:"In the liquidity-preference theory, the interest rate adjusts to balance",opts:["money supply and money demand", "saving and government spending", "exports and imports", "taxes and transfers"],exp:"Money demand slopes down; the central bank sets money supply."},
{id:"ep-n10",cat:"n",q:"A higher interest rate reduces the quantity of money demanded because",opts:["the opportunity cost of holding money rises", "prices fall", "income rises", "banks hold more reserves"],exp:"Holding cash means giving up the interest a bond would pay."},
{id:"ep-n11",cat:"n",q:"An increase in the money supply lowers interest rates, which raises",opts:["investment spending", "the reserve ratio", "the government deficit", "imports of gold"],exp:"Cheaper loans make more investment projects worthwhile."},
{id:"ep-n12",cat:"n",q:"Contractionary monetary policy is used when the economy has",opts:["an inflationary gap", "a recessionary gap", "high unemployment and falling prices", "a budget surplus"],exp:"Reducing demand closes an inflationary gap."},
{id:"ep-n13",cat:"n",q:"Expansionary monetary policy is used when the economy has",opts:["a recessionary gap", "an inflationary gap", "very low unemployment", "rapid inflation"],exp:"Raising demand closes a recessionary gap."},
{id:"ep-n14",cat:"n",q:"Inflation targeting means the central bank",opts:["announces a target range for inflation and sets policy to reach it", "fixes the price of every good", "targets the government budget", "targets the stock market"],exp:"The Bank of Thailand uses a headline inflation target."},
{id:"ep-n15",cat:"n",q:"A time lag in monetary policy means that",opts:["changes in interest rates affect spending only after months", "policy works immediately", "policy never works", "only taxes can change"],exp:"Firms and households take time to change their plans."},
{id:"ep-n16",cat:"n",q:"The central bank as lender of last resort",opts:["lends to banks in trouble to prevent a financial panic", "lends to the government only", "lends to households for houses", "never lends money"],exp:"It provides liquidity when banks cannot borrow elsewhere."},
{id:"ep-n17",cat:"n",q:"The interest rate on overnight loans between banks is the",opts:["interbank (policy) rate", "prime rate for houses", "inflation rate", "exchange rate"],exp:"Central banks steer this short-term rate."},
{id:"ep-n18",cat:"n",q:"If the central bank raises its policy rate, commercial banks usually",opts:["raise their loan rates", "lower their loan rates", "stop taking deposits", "stop all lending"],exp:"Higher funding costs are passed on to borrowers."},
{id:"ep-n19",cat:"n",q:"In the short run, a fall in the money supply most likely causes",opts:["lower output and employment", "higher output", "a higher price level immediately", "no change in interest rates"],exp:"Interest rates rise, spending falls and AD shifts left."},
{id:"ep-n20",cat:"n",q:"In the long run, an increase in the money supply mainly raises",opts:["the price level", "real GDP", "the natural rate of unemployment", "productivity"],exp:"Money is neutral in the long run."},
{id:"ep-n21",cat:"n",q:"Monetary neutrality means that changes in the money supply",opts:["do not affect real variables in the long run", "affect only real GDP", "change the natural rate of unemployment", "have no effect on prices"],exp:"Prices adjust; real output returns to its natural level."},
{id:"ep-n22",cat:"n",q:"Quantitative easing is",opts:["large central bank purchases of bonds and other assets to lower long-term rates", "a tax cut", "a rise in the reserve requirement", "government spending on roads"],exp:"It is used when short-term rates are already near zero."},
{id:"ep-n23",cat:"n",q:"The Fisher effect says that a rise in expected inflation leads to",opts:["an equal rise in the nominal interest rate", "a fall in the nominal interest rate", "no change in nominal rates", "a fall in the price level"],exp:"Nominal rate = real rate + expected inflation."},
{id:"ep-n24",cat:"n",q:"If the nominal interest rate is 6% and inflation is 2%, the real interest rate is about",opts:["4%", "8%", "3%", "12%"],exp:"Real ≈ nominal − inflation = 6% − 2% = 4%."},
{id:"ep-n25",cat:"n",q:"When interest rates rise, the domestic currency tends to",opts:["appreciate as foreign funds flow in", "depreciate", "stay fixed", "become worthless"],exp:"Higher returns attract capital inflows."},
{id:"ep-n26",cat:"n",q:"A stronger baht after a rate rise tends to",opts:["reduce net exports", "increase net exports", "increase inflation", "increase money supply"],exp:"Thai goods become more expensive abroad."},
// ---------- Fiscal policy (more) (cat f), added 18 Nov 2026 ----------
{id:"ep-f16",cat:"f",q:"Automatic stabilisers are",opts:["taxes and transfers that change on their own with the business cycle", "new laws passed during a recession", "central bank rate changes", "import quotas"],exp:"In a recession, tax revenue falls and benefits rise without new action."},
{id:"ep-f17",cat:"f",q:"Unemployment benefits act as an automatic stabiliser because they",opts:["rise in recessions and support spending", "rise in booms", "are paid only in booms", "raise taxes in recessions"],exp:"They support incomes when jobs are lost."},
{id:"ep-f18",cat:"f",q:"With a marginal propensity to consume (MPC) of 0.8, the spending multiplier is",opts:["5", "0.8", "1.25", "8"],exp:"Multiplier = 1 ÷ (1 − MPC) = 1 ÷ 0.2 = 5."},
{id:"ep-f19",cat:"f",q:"With an MPC of 0.75, a 100 million increase in government spending can raise GDP by up to",opts:["400 million", "100 million", "75 million", "133 million"],exp:"Multiplier = 1 ÷ 0.25 = 4, so 100 × 4 = 400 million."},
{id:"ep-f20",cat:"f",q:"Contractionary fiscal policy means",opts:["cutting government spending or raising taxes", "raising government spending", "cutting taxes", "buying government bonds"],exp:"It reduces aggregate demand to cool an overheating economy."},
{id:"ep-f21",cat:"f",q:"National (public) debt is",opts:["the total of past budget deficits minus surpluses", "one year's budget deficit", "the money supply", "the trade deficit"],exp:"Each year's deficit adds to the debt."},
{id:"ep-f22",cat:"f",q:"A budget surplus occurs when",opts:["tax revenue is greater than government spending", "spending is greater than tax revenue", "imports exceed exports", "the money supply falls"],exp:"A surplus can be used to repay debt."},
{id:"ep-f23",cat:"f",q:"Supply-side fiscal policy, such as lower tax rates on work and investment, aims mainly to",opts:["raise aggregate supply over time", "raise the price level", "reduce saving", "raise interest rates"],exp:"Lower marginal tax rates may increase incentives to work and invest."},
// ---------- Inflation (more) (cat i), added 18 Nov 2026 ----------
{id:"ep-i16",cat:"i",q:"The Consumer Price Index (CPI) measures",opts:["the cost of a fixed basket of goods and services bought by a typical consumer", "the prices of all goods produced in a country", "the price of shares", "the wages of workers"],exp:"CPI tracks consumer prices; the GDP deflator covers all domestic output."},
{id:"ep-i17",cat:"i",q:"If the CPI rises from 120 to 126, the inflation rate is",opts:["5%", "6%", "26%", "4.8%"],exp:"(126 − 120) ÷ 120 = 0.05 = 5%."},
{id:"ep-i18",cat:"i",q:"Unexpected inflation tends to hurt",opts:["lenders and people on fixed incomes", "borrowers with fixed-rate loans", "people who own goods that rise in price", "the government as a borrower"],exp:"Money repaid is worth less than expected."},
{id:"ep-i19",cat:"i",q:"Demand-pull inflation happens when",opts:["aggregate demand grows faster than the economy can produce","production costs such as wages rise","the price of oil falls","the central bank sells bonds"],exp:"Too much spending chasing too few goods pulls prices up; AD shifts right beyond full employment."},
// ---------- Business cycle (more) (cat b), added 18 Nov 2026 ----------
{id:"ep-b19",cat:"b",q:"A recession is usually described as",opts:["a period of falling real GDP, often two quarters in a row", "a period of rising prices", "a period of rising real GDP", "a fall in the stock market only"],exp:"Output and incomes fall and unemployment rises."},
{id:"ep-b20",cat:"b",q:"The four phases of the business cycle are",opts:["expansion, peak, contraction and trough", "growth, inflation, deflation and boom", "saving, investing, spending and lending", "supply, demand, price and quantity"],exp:"The economy moves from a trough through expansion to a peak and back."},
{id:"ep-b21",cat:"b",q:"Cyclical unemployment is",opts:["unemployment caused by a fall in total spending during a recession", "unemployment from changing jobs", "unemployment from a mismatch of skills", "unemployment that never changes"],exp:"It rises in recessions and falls in expansions."},
{id:"ep-b22",cat:"b",q:"The natural rate of unemployment includes",opts:["frictional and structural unemployment", "only cyclical unemployment", "all unemployment in a recession", "only people who stopped looking for work"],exp:"It is the unemployment that remains when the economy is at full employment."},
// Added 19 Nov 2026: 20 more per macro chapter (ids continue per chapter)
{id:"ep-g21",cat:"g",q:"Which payment is a transfer payment and therefore NOT counted in GDP?",opts:["A government pension paid to a retired person","The salary of a government teacher","A government purchase of new computers for schools","A payment to a firm that builds a public road"],exp:"A transfer payment is not made in exchange for current production. The salary, the computers and the road are all payments for goods or services produced."},
{id:"ep-g22",cat:"g",q:"A used car is resold this year. It is not counted in this year's GDP because",opts:["it was already counted in the year it was produced","car dealers earn no income","used cars are intermediate goods","the price of used cars is unknown"],exp:"GDP counts only goods and services produced in the current period. Only the dealer's service fee for the resale would be counted."},
{id:"ep-g23",cat:"g",q:"Net exports are negative when",opts:["imports are greater than exports","exports are greater than imports","government spending is greater than taxes","investment is greater than saving"],exp:"Net exports = X - M, so the value is negative when the country buys more from abroad than it sells abroad."},
{id:"ep-g24",cat:"g",q:"Which item is counted as gross private domestic investment (I)?",opts:["A firm builds a new factory","A household buys shares of stock","The government buys a new bridge","A bank buys a government bond"],exp:"Investment means spending on new capital goods (and new housing and inventories). Buying shares or bonds only moves existing financial assets."},
{id:"ep-g25",cat:"g",q:"C = 600, I = 150, G = 200, X = 100 and M = 120 (billion). Expenditure-approach GDP is",opts:["930 billion","1,170 billion","1,050 billion","830 billion"],exp:"GDP = C + I + G + (X - M) = 600 + 150 + 200 + (100 - 120) = 930.\n1,170 = adds imports instead of subtracting · 1,050 = forgets imports · 830 = forgets exports"},
{id:"ep-g26",cat:"g",q:"Which transaction involves an intermediate good?",opts:["A bakery buys flour to make bread to sell","A household buys a cake to eat","A firm buys a new oven for its bakery","The government buys a fire engine"],exp:"An intermediate good is used up in producing something else that is sold. The cake is a final consumption good, and the oven and fire engine are final capital goods."},
{id:"ep-g27",cat:"g",q:"A Thai citizen works in Japan and earns income there. This income is part of Thailand's",opts:["GNP but not Thailand's GDP","GDP but not Thailand's GNP","both GDP and GNP","neither GDP nor GNP"],exp:"GNP counts income earned by a country's residents anywhere in the world. GDP counts only production inside the country's borders."},
{id:"ep-g28",cat:"g",q:"GDP is 3,000 billion baht and the population is 60 million. GDP per capita is",opts:["50,000 baht","5,000 baht","500 baht","180,000 baht"],exp:"3,000 billion / 60 million = 3,000,000 million / 60 million = 50,000.\n5,000 and 500 = decimal slips · 180,000 = multiplied instead of divided"},
{id:"ep-g29",cat:"g",q:"Nominal GDP is 1,260 and the GDP chain price index is 120 (base = 100). Real GDP is",opts:["1,050","1,512","1,140","105"],exp:"Real GDP = Nominal GDP / index x 100 = 1,260 / 120 x 100 = 1,050.\n1,512 = multiplied by 1.2 · 1,140 = subtracted 120 · 105 = forgot x 100"},
{id:"ep-g30",cat:"g",q:"Spending on cleaning up an oil spill raises GDP. This shows that GDP",opts:["counts repair spending as output without subtracting the damage","excludes government purchases","is adjusted for environmental harm","counts only exports"],exp:"Economic bads such as pollution are not subtracted from GDP, while the money spent to clean them up is counted as production."},
{id:"ep-g31",cat:"g",q:"Which activity is NOT counted in GDP?",opts:["A parent cooks dinner for the family at home","A restaurant chef cooks dinner for customers","A paid nanny looks after children","A paid cleaner cleans an office"],exp:"Nonmarket production is hard to value, so unpaid household work is left out. The same work done for pay is counted."},
{id:"ep-g32",cat:"g",q:"Counting both the steel sold to a carmaker and the full price of the finished car would cause",opts:["double counting, so GDP is overstated","GDP to be understated","net exports to fall","the GDP deflator to equal 100"],exp:"Steel is an intermediate good whose value is already inside the car's price. Counting both counts the steel twice."},
{id:"ep-g33",cat:"g",q:"A farmer sells wheat for 40 to a miller. The miller sells flour for 70 to a baker. The baker sells bread for 120 to consumers. Total contribution to GDP is",opts:["120","230","190","70"],exp:"Only the final good counts: 120. The sum of value added (40 + 30 + 50) is also 120.\n230 = adds every sale · 190 = leaves out the farmer's wheat · 70 = counts only the flour"},
{id:"ep-g34",cat:"g",q:"Which pair of items is part of national income in the income approach to GDP?",opts:["Wages and corporate profits","Consumption and investment","Taxes and transfer payments","Imports and exports"],exp:"The income approach adds up what factors of production earn: wages, rent, interest and profits. Consumption, investment, imports and exports belong to the expenditure approach."},
{id:"ep-g35",cat:"g",q:"Nominal GDP rises 8% while prices rise 3%. Real GDP grows by about",opts:["5%","11%","8%","3%"],exp:"Real growth is about nominal growth minus inflation: 8% - 3% = 5%."},
{id:"ep-g36",cat:"g",q:"A city buys new buses for its public transport system. In the expenditure approach this counts as",opts:["government spending (G)","consumption (C)","net exports","a transfer payment"],exp:"Purchases of goods and services by any level of government are G. A transfer payment would involve no purchase of output."},
{id:"ep-g37",cat:"g",q:"The GDP deflator is 80 in 2020, and the base year is 2022 (deflator 100). This means",opts:["prices in 2020 were 20% lower than in the base year","prices in 2020 were 80% higher than in the base year","real GDP in 2020 was 80","2020 is the base year"],exp:"The index shows the price level relative to the base year (= 100). 80 means prices were 20% below base-year prices."},
{id:"ep-g38",cat:"g",q:"Which measure is best for comparing living standards in two countries with very different populations?",opts:["Real GDP per capita","Nominal GDP","Total real GDP","Nominal GDP growth"],exp:"Dividing by population adjusts for size, and using real GDP removes price differences."},
{id:"ep-g39",cat:"g",q:"A Thai household buys a Japanese car. The effect on Thai GDP is",opts:["none, because the rise in C is cancelled by an equal rise in M","an increase equal to the price of the car","a decrease equal to the price of the car","an increase in net exports"],exp:"The purchase raises consumption but is also an import, which is subtracted. Only the Thai dealer's margin and service would be domestic output."},
{id:"ep-g40",cat:"g",q:"A car maker produces cars that remain unsold at the end of the year. In GDP they are counted",opts:["as inventory investment in the year they were produced","only when they are sold","as consumption","in the following year"],exp:"GDP measures production in the period. Unsold goods are added to inventories, which counts as investment."},
{id:"ep-i20",cat:"i",q:"A basket costs 400 in the base year and 460 this year. The CPI this year is",opts:["115","87","15","140"],exp:"CPI = cost of basket now / cost in base year x 100 = 460 / 400 x 100 = 115.\n87 = divided the other way · 15 = the percent change, not the index"},
{id:"ep-i21",cat:"i",q:"The CPI rises from 110 to 121. The inflation rate is",opts:["10%","11%","9.1%","21%"],exp:"(121 - 110) / 110 x 100 = 10%.\n11% = the index change in points · 9.1% = divided by the new CPI"},
{id:"ep-i22",cat:"i",q:"Which problem makes the CPI overstate inflation?",opts:["A fixed basket ignores substitution toward cheaper goods","The basket is updated every month","It includes only imported goods","It leaves out housing costs"],exp:"Consumers switch away from goods that become expensive, but a fixed basket keeps counting the old quantities, so the cost of living appears to rise faster."},
{id:"ep-i23",cat:"i",q:"A new phone model costs 20% more than last year's, but it is much faster with a better camera. If the CPI counts the whole 20% as a price rise, the CPI",opts:["overstates inflation","understates inflation","measures inflation correctly","is not affected"],exp:"Part of the higher price pays for better quality. Treating all of it as a pure price increase makes the CPI too high."},
{id:"ep-i24",cat:"i",q:"A worker earns 30,000 per month and the CPI is 125 (base = 100). Real income is",opts:["24,000","37,500","29,875","3,750"],exp:"Real income = nominal income / (CPI / 100) = 30,000 / 1.25 = 24,000.\n37,500 = multiplied by the index · 29,875 = subtracted 125"},
{id:"ep-i25",cat:"i",q:"Which price index includes the prices of machines bought by firms?",opts:["The GDP deflator","The CPI","Both indexes in the same way","Neither index"],exp:"The GDP deflator covers all final goods and services produced in the country, including investment and government purchases. The CPI covers only consumer purchases."},
{id:"ep-i26",cat:"i",q:"The price of imported consumer electronics rises sharply. Which index is affected?",opts:["The CPI, but not the GDP deflator","The GDP deflator, but not the CPI","Both indexes","Neither index"],exp:"The CPI covers what consumers buy, including imports. The GDP deflator covers only goods produced inside the country."},
{id:"ep-i27",cat:"i",q:"Who is most likely to gain from unexpected inflation?",opts:["A borrower with a fixed-rate loan","A lender with a fixed-rate loan","A retiree on a fixed pension","A saver holding cash"],exp:"The borrower repays with money that has lost purchasing power. Lenders, pensioners and cash holders lose."},
{id:"ep-i28",cat:"i",q:"A wage-price spiral starts when",opts:["workers demand higher pay after prices rise, which raises firms' costs and leads to higher prices again","firms cut prices to attract buyers","the money supply falls","the government runs a budget surplus"],exp:"Higher prices lead to higher wage demands, then higher costs, then higher prices, and the cycle repeats at a higher level of inflation."},
{id:"ep-i29",cat:"i",q:"A household keeps 100,000 baht in cash for a year while inflation is 5%. The purchasing power of the cash falls by about",opts:["5%","0%, because the number of baht is unchanged","10%","95%"],exp:"The cash still equals 100,000 baht, but each baht buys about 5% less."},
{id:"ep-i30",cat:"i",q:"The CPI is 100 in 2020 and 130 in 2025. The price of the basket rose by",opts:["30% over the five years","130% over the five years","23% over the five years","6% per year exactly"],exp:"(130 - 100) / 100 = 30% over the whole period.\n23% = divided by the new index (100/130) · 6% per year = just dividing 30 by 5"},
{id:"ep-i31",cat:"i",q:"Hyperinflation is usually linked to",opts:["very fast money creation to finance government deficits","a fast fall in the money supply","a government budget surplus","rapid growth of real GDP"],exp:"When the government prints money to pay its bills, the money supply grows far faster than output, so prices explode."},
{id:"ep-i32",cat:"i",q:"Which event is most likely to cause demand-pull inflation when the economy is near full employment?",opts:["A large increase in government spending","A sharp rise in world oil prices","A rise in labour productivity","A fall in consumer confidence"],exp:"Higher spending pushes up total demand when firms cannot increase output much, so prices rise. An oil price rise would be cost-push."},
{id:"ep-i33",cat:"i",q:"Your income rises 8% while prices rise 5%. Your real income rises by about",opts:["3%","8%","13%","-3%"],exp:"Real income growth is about nominal growth minus inflation: 8% - 5% = 3%."},
{id:"ep-i34",cat:"i",q:"Why can falling prices (deflation) harm the economy?",opts:["Consumers may delay purchases, which lowers demand and output","The real value of debts falls, which helps borrowers","Wages always rise faster than prices","Firms' revenues rise"],exp:"If people expect lower prices later, they postpone buying. Lower demand cuts output and jobs, and the real burden of debts actually rises."},
{id:"ep-i35",cat:"i",q:"Inflation falls from 6% to 2%. This is called",opts:["disinflation","deflation","hyperinflation","stagflation"],exp:"Prices still rise, but more slowly. Deflation would need a negative inflation rate."},
{id:"ep-i36",cat:"i",q:"Housing has a weight of 30% in the CPI basket. If rents and housing costs rise 10% and everything else is unchanged, the CPI rises by about",opts:["3%","10%","30%","0.3%"],exp:"0.30 x 10% = 3%."},
{id:"ep-i37",cat:"i",q:"A bag of rice costs 50 in 2015 (CPI = 100) and 80 in 2025 (CPI = 160). In real terms the price of rice has",opts:["not changed","risen by 60%","fallen by 20%","doubled"],exp:"Deflated price = 80 / 160 x 100 = 50, the same as in 2015. The rise matches the general price level."},
{id:"ep-i38",cat:"i",q:"A retiree receives a fixed pension of 15,000 per month. The CPI rises from 100 to 125. The pension is now worth, in base-year prices,",opts:["12,000","18,750","14,875","15,000"],exp:"15,000 / 1.25 = 12,000.\n18,750 = multiplied by 1.25 · 14,875 = subtracted 125"},
{id:"ep-i39",cat:"i",q:"If households and firms expect higher inflation, this tends to",opts:["make actual inflation rise, as workers ask for higher wages and firms raise prices early","lower inflation, as people save more","have no effect on prices","cause deflation"],exp:"Expectations are self-fulfilling: wage demands and price setting build in the expected inflation."},
{id:"ep-b23",cat:"b",q:"There are 114 million people employed and 6 million unemployed. The unemployment rate is",opts:["5%","5.3%","6%","20%"],exp:"Unemployment rate = 6 / (114 + 6) x 100 = 5%.\n5.3% = divided by the employed only · 20% = divided by 30"},
{id:"ep-b24",cat:"b",q:"A man stops looking for work because he believes no one will hire him. He is counted as",opts:["a discouraged worker, outside the labour force","unemployed","employed","cyclically employed"],exp:"Official unemployment counts only people who are actively looking for work, so discouraged workers drop out of the labour force."},
{id:"ep-b25",cat:"b",q:"A part-time worker who wants a full-time job is counted as",opts:["employed","unemployed","a discouraged worker","outside the labour force"],exp:"Anyone with paid work of at least one hour a week is employed, so the official rate does not capture underemployment."},
{id:"ep-b26",cat:"b",q:"Which person is NOT part of the civilian labour force?",opts:["A full-time student who is not looking for work","A person with a part-time job","A person actively looking for work","A person who works 20 unpaid hours in a family shop"],exp:"The labour force is people with jobs plus unemployed people who are looking. A student who is not looking is outside it."},
{id:"ep-b27",cat:"b",q:"At the peak of a business cycle, real GDP is",opts:["at its highest point before a downturn begins","at its lowest point","growing fastest","equal to nominal GDP"],exp:"The peak is the top of the expansion. After it, real GDP starts to fall into a recession."},
{id:"ep-b28",cat:"b",q:"Which is most likely to rise during a recession?",opts:["The unemployment rate","Consumer spending","Business investment","Tax revenue"],exp:"Falling output means fewer jobs. Spending, investment and tax revenue usually fall."},
{id:"ep-b29",cat:"b",q:"Widespread use of robots replaces many factory jobs. This mainly increases",opts:["structural unemployment","frictional unemployment","cyclical unemployment","the natural labour force"],exp:"Workers' skills no longer match the jobs available, which is structural."},
{id:"ep-b30",cat:"b",q:"A worker quits her job to search for a better one. This is an example of",opts:["frictional unemployment","structural unemployment","cyclical unemployment","a discouraged worker"],exp:"She is between jobs and searching, so it is short-term frictional unemployment."},
{id:"ep-b31",cat:"b",q:"The natural rate of unemployment is 5% and the actual rate is 8%. The cyclical unemployment rate is",opts:["3 percentage points","5 percentage points","8 percentage points","13 percentage points"],exp:"Cyclical = actual - natural = 8% - 5% = 3 percentage points."},
{id:"ep-b32",cat:"b",q:"Real GDP index in five quarters: 100, 102, 99, 96, 98. Which quarter is the trough?",opts:["Quarter 4","Quarter 2","Quarter 3","Quarter 5"],exp:"The trough is the lowest point, 96, in quarter 4. Quarter 2 (102) is the peak."},
{id:"ep-b33",cat:"b",q:"Real GDP index in five quarters: 100, 103, 101, 100, 104. Under the usual two-quarter rule, was there a recession?",opts:["Yes, because real GDP fell in two consecutive quarters","No, because real GDP never fell below 100","No, because real GDP rose in the last quarter","Only if unemployment also rose"],exp:"Real GDP fell from 103 to 101 and then to 100, two quarters in a row. The later recovery does not erase the recession."},
{id:"ep-b34",cat:"b",q:"Unemployment falls from 6% to 5% because many job seekers give up searching, and no new jobs are created. This shows that",opts:["the unemployment rate can fall without any improvement in employment","the economy has reached full employment","cyclical unemployment has increased","the labour force has grown"],exp:"People who stop searching leave the labour force, so the rate falls even though no one found a job."},
{id:"ep-b35",cat:"b",q:"A woman works 20 unpaid hours a week in her family's shop. She is counted as",opts:["employed","unemployed","a discouraged worker","outside the labour force"],exp:"Unpaid work of 15 hours or more a week in a family business counts as employed."},
{id:"ep-b36",cat:"b",q:"A student works 5 paid hours a week and would like more work. Official statistics count him as",opts:["employed","unemployed","underemployed only","outside the labour force"],exp:"One hour of paid work in the survey week is enough to be counted as employed."},
{id:"ep-b37",cat:"b",q:"Which component of spending usually falls first and furthest in a recession?",opts:["Business investment in equipment and buildings","Spending on food and basic services","Government purchases","Imports"],exp:"Firms cut investment quickly when sales and profit expectations fall, so I is the most volatile component."},
{id:"ep-b38",cat:"b",q:"Which policy is aimed mainly at reducing cyclical unemployment?",opts:["Raising aggregate demand with expansionary policy","Retraining programmes for displaced workers","Online job-matching services","Cutting the natural rate of unemployment"],exp:"Cyclical unemployment comes from too little spending in a recession, so the fix is higher aggregate demand."},
{id:"ep-b39",cat:"b",q:"Which policy would best reduce frictional unemployment?",opts:["Better job-matching information services","Expansionary fiscal policy","A larger government budget deficit","Raising the reserve requirement"],exp:"Frictional unemployment comes from the time it takes to match workers and jobs, so better information shortens the search."},
{id:"ep-b40",cat:"b",q:"Which policy would best reduce structural unemployment?",opts:["Retraining programmes for workers whose skills are outdated","Cutting interest rates","Raising income taxes","Increasing the money supply"],exp:"Structural unemployment comes from a mismatch of skills, so retraining addresses the cause."},
{id:"ep-b41",cat:"b",q:"A cost of high cyclical unemployment to the economy is",opts:["lost output, because actual real GDP is below potential","higher inflation in every case","higher tax revenue","faster growth in productivity"],exp:"Idle workers produce nothing, so the economy produces less than it could."},
{id:"ep-b42",cat:"b",q:"Adults: 100 million. Employed: 72 million. Unemployed: 8 million. The rest are not in the labour force. The unemployment rate is",opts:["10%","8%","11.1%","20%"],exp:"Labour force = 72 + 8 = 80 million. Rate = 8 / 80 x 100 = 10%.\n8% = divided by the whole adult population · 11.1% = divided by the employed only"},
{id:"ep-a16",cat:"a",q:"A global recession reduces the demand for a country's exports. On an AD-AS diagram this",opts:["shifts aggregate demand to the left","shifts aggregate demand to the right","shifts aggregate supply to the right","moves along the AD curve"],exp:"Exports are part of X in C + I + G + (X - M). Lower X reduces total spending at every price level."},
{id:"ep-a17",cat:"a",q:"Firms become more optimistic about future profits and increase investment spending. This",opts:["shifts aggregate demand to the right","shifts aggregate demand to the left","shifts aggregate supply to the left","moves along the AS curve"],exp:"Investment is a component of AD, so more of it raises spending at every price level."},
{id:"ep-a18",cat:"a",q:"World oil prices fall sharply. On an AD-AS diagram the effect is that",opts:["aggregate supply shifts right, so the price level falls and real GDP rises","aggregate supply shifts left, so the price level rises","aggregate demand shifts left","aggregate demand shifts right with no change in prices"],exp:"Lower resource prices reduce production costs, which shifts AS to the right."},
{id:"ep-a19",cat:"a",q:"The government raises taxes on business operations, raising firms' costs. Aggregate supply",opts:["shifts to the left","shifts to the right","does not change","becomes vertical"],exp:"Higher taxes on firms act like higher production costs, so firms supply less at each price level."},
{id:"ep-a20",cat:"a",q:"A new technology raises output per worker across the economy. The result is",opts:["AS shifts right: a lower price level and higher real GDP","AS shifts left: a higher price level and lower real GDP","AD shifts left: a lower price level","AD shifts right: a higher price level"],exp:"Technology lowers costs, so aggregate supply increases and the equilibrium moves to more output at lower prices."},
{id:"ep-a21",cat:"a",q:"Wages rise much faster than labour productivity across the economy. Aggregate supply",opts:["shifts to the left","shifts to the right","is unchanged","shifts right and AD shifts left"],exp:"Higher labour costs per unit of output reduce the quantity firms are willing to supply at each price level."},
{id:"ep-a22",cat:"a",q:"The baht strengthens a lot, so exports fall and imports rise. This",opts:["shifts aggregate demand to the left","shifts aggregate demand to the right","shifts aggregate supply to the right","shifts aggregate supply to the left"],exp:"Net exports (X - M) fall, which lowers total spending at every price level."},
{id:"ep-a23",cat:"a",q:"What does the vertical axis of the AD-AS diagram show?",opts:["The price level index","The price of one good","Real GDP","The quantity of one good"],exp:"In AD-AS the axes are the overall price level (such as a CPI) and real GDP, unlike a single-market supply and demand graph."},
{id:"ep-a24",cat:"a",q:"What does the horizontal axis of the AD-AS diagram show?",opts:["Real GDP","The price level","The quantity of one good","The nominal interest rate"],exp:"The horizontal axis measures total output, or real GDP."},
{id:"ep-a25",cat:"a",q:"A rise in the domestic price level makes exports more expensive abroad and imports cheaper at home. As a result, the quantity of real GDP demanded",opts:["decreases","increases","does not change","becomes zero"],exp:"This is the foreign-trade effect: net exports fall as prices rise, which is one reason AD slopes downward."},
{id:"ep-a26",cat:"a",q:"If both AD and AS shift to the right, real GDP will",opts:["increase, while the price level may rise, fall or stay the same","decrease, while the price level rises","stay the same, while the price level rises","stay the same, while the price level falls"],exp:"Both shifts raise output. The change in the price level depends on which shift is larger."},
{id:"ep-a27",cat:"a",q:"If AD shifts to the left and AS shifts to the left, real GDP will",opts:["fall, while the effect on the price level is uncertain","rise, while the price level falls","rise, while the price level rises","stay the same"],exp:"Both shifts reduce output. The price effect depends on the relative size of the shifts."},
{id:"ep-a28",cat:"a",q:"Keynesian economists say that during a deep recession the government should",opts:["raise aggregate demand to restore full employment","wait for wages and prices to fall","cut government spending to balance the budget","raise taxes to reduce prices"],exp:"Keynesians believe wages and prices are slow to fall, so the economy can stay below full employment unless demand is increased."},
{id:"ep-a29",cat:"a",q:"The short-run macroeconomic equilibrium is found where",opts:["the AD curve crosses the AS curve","the AS curve meets the vertical axis","the AD curve is vertical","real GDP equals nominal GDP"],exp:"Equilibrium price level and real GDP are determined by the intersection of AD and AS."},
{id:"ep-a30",cat:"a",q:"If short-run equilibrium real GDP is above full-employment GDP, the economy faces",opts:["upward pressure on wages and prices","rising unemployment","falling inflation","a decline in the price level"],exp:"Output above the full-employment level strains resources, so wages and prices tend to rise."},
{id:"ep-a31",cat:"a",q:"Which change in AD-AS produces stagflation, meaning higher prices and lower output?",opts:["A leftward shift of aggregate supply","A rightward shift of aggregate supply","A rightward shift of aggregate demand in the Keynesian range","A leftward shift of aggregate demand in the classical range"],exp:"When AS shifts left, the equilibrium moves to a higher price level and lower real GDP."},
{id:"ep-a32",cat:"a",q:"A change in the price level, with nothing else changed, causes",opts:["a movement along the AD curve","a rightward shift of AD","a leftward shift of AS","a shift of both curves"],exp:"A price-level change moves the economy along AD. Only non-price determinants (C, I, G, X - M) shift the curve."},
{id:"ep-a33",cat:"a",q:"In the classical view of a recession, the economy returns to full employment because",opts:["wages and prices fall, shifting AS to the right","the government raises spending","AD shifts permanently to the left","the AS curve is horizontal"],exp:"Classical economists assume flexible wages and prices, so the economy corrects itself."},
{id:"ep-a34",cat:"a",q:"Technological progress shifts AS to the right while AD stays the same. The price level",opts:["falls and real GDP rises","rises and real GDP rises","falls and real GDP falls","rises and real GDP falls"],exp:"A bigger supply at every price level lowers the equilibrium price and raises output."},
{id:"ep-a35",cat:"a",q:"A government subsidy to producers shifts",opts:["aggregate supply to the right","aggregate supply to the left","aggregate demand to the left","aggregate demand to the right"],exp:"A subsidy lowers firms' production costs, so they supply more at each price level."},
{id:"ep-d21",cat:"d",q:"Real GDP is 600 billion and the population is 20 million. Real GDP per capita is",opts:["30,000","3,000","12,000","300"],exp:"600 billion / 20 million = 30,000."},
{id:"ep-d22",cat:"d",q:"Real GDP rises from 2,000 to 2,100. The growth rate is",opts:["5%","4.8%","100%","2.1%"],exp:"(2,100 - 2,000) / 2,000 x 100 = 5%.\n4.8% = divided by the new value"},
{id:"ep-d23",cat:"d",q:"By the rule of 70, an economy growing at 5% a year doubles its output in about",opts:["14 years","35 years","7 years","70 years"],exp:"70 / 5 = 14 years."},
{id:"ep-d24",cat:"d",q:"The vicious circle of poverty describes how",opts:["low income limits saving and investment, which keeps income low","high income raises the price level","rapid growth lowers saving","foreign aid causes inflation"],exp:"Poor countries struggle to save and invest, so productivity and income stay low."},
{id:"ep-d25",cat:"d",q:"Which is an example of infrastructure?",opts:["A national network of highways and ports","A private restaurant chain","A stock of consumer goods","A government pension payment"],exp:"Infrastructure is capital such as roads, ports, airports and water systems, usually supplied by government."},
{id:"ep-d26",cat:"d",q:"Population grows 3% while real GDP grows 2%. Real GDP per person",opts:["falls by about 1%","rises by about 1%","rises by about 5%","does not change"],exp:"Per capita growth is about GDP growth minus population growth: 2% - 3% = -1%."},
{id:"ep-d27",cat:"d",q:"Which is a measure of quality of life that goes beyond GDP per capita?",opts:["Life expectancy","The stock market index","The inflation rate","The exchange rate"],exp:"Development includes health and education outcomes such as life expectancy and literacy."},
{id:"ep-d28",cat:"d",q:"Which is typical of a less-developed country?",opts:["A large share of workers in agriculture and little capital per worker","Mostly high-tech factories","A very high literacy rate","A very high saving rate"],exp:"LDCs rely on farming and lack capital and well-educated labour."},
{id:"ep-d29",cat:"d",q:"Appropriate technology matters for LDCs because",opts:["many advanced technologies made for rich countries do not fit labour-abundant, capital-poor economies","technology never raises productivity","LDCs are not able to use any machines","technology only matters for exports"],exp:"Technology must suit local resources and skills to raise productivity."},
{id:"ep-d30",cat:"d",q:"Japan and Israel have high living standards despite few natural resources. This suggests that",opts:["natural resources are not required for development","natural resources are the only source of growth","capital is not important","trade lowers growth"],exp:"Human resources, capital, technology and institutions can matter more than natural resources."},
{id:"ep-d31",cat:"d",q:"Beta invests more in capital goods than Alpha. In the future Beta's production possibilities curve will most likely",opts:["shift outward by more than Alpha's","shift inward","stay the same as Alpha's","become a straight line"],exp:"Capital goods raise future productive capacity, so the curve shifts out further."},
{id:"ep-d32",cat:"d",q:"Which government action most supports economic growth?",opts:["Enforcing property rights and maintaining law and order","Setting price controls on all goods","Using high trade barriers to protect all industries","Fixing the exchange rate far from its market value"],exp:"Secure property rights and stable rules encourage saving, investment and work."},
{id:"ep-d33",cat:"d",q:"Which is an example of investment in human capital?",opts:["Funding a vocational training programme for workers","Buying a new machine for a factory","Building a highway","Buying shares of a company"],exp:"Human capital is the knowledge and skills of workers, built through education and training."},
{id:"ep-d34",cat:"d",q:"Comparing GDP per capita across countries at market exchange rates can mislead because",opts:["exchange rates fluctuate and do not reflect what money buys at home","GDP is always measured in the same currency","GDP excludes population","prices are the same everywhere"],exp:"Exchange-rate swings change measured GDP per capita even when real output has not changed."},
{id:"ep-d35",cat:"d",q:"Country A and Country B have the same GDP per capita. In A income is shared fairly equally, while in B a few people hold most of it. GDP per capita",opts:["does not show this difference","shows that A is richer","shows that B is richer","shows both have equal inequality"],exp:"GDP per capita is an average and says nothing about how income is distributed."},
{id:"ep-d36",cat:"d",q:"To build more capital goods, a country must",opts:["give up some current consumption by saving","reduce its population to zero","stop trading with other countries","raise the price level"],exp:"Resources used to make capital cannot be used for consumer goods now, so saving is required."},
{id:"ep-d37",cat:"d",q:"Countries with greater economic freedom tend to have",opts:["higher GDP per capita","lower life expectancy","less trade","lower literacy"],exp:"Economic freedom ratings are strongly correlated with GDP per capita and other development measures."},
{id:"ep-d38",cat:"d",q:"A country's real GDP per capita rises, but life expectancy and literacy fall. This is best described as",opts:["growth without development","development without growth","neither growth nor development","both growth and development"],exp:"Development includes quality-of-life measures as well as income."},
{id:"ep-d39",cat:"d",q:"Raising the literacy rate helps growth mainly because",opts:["workers become more productive and can adopt new technology","it lowers the price level","it increases natural resources","it reduces the need for capital"],exp:"Education builds human capital, which raises output per worker."},
{id:"ep-d40",cat:"d",q:"Why might a low-income country have a low saving rate?",opts:["Most income is needed just for basic necessities","Interest rates are guaranteed to be very high","Citizens prefer to hold gold","Saving is illegal"],exp:"When income is near subsistence, little is left to save, which limits investment."},
{id:"ep-m26",cat:"m",q:"A baker wants shoes, but the shoemaker does not want bread. This problem of barter is the lack of",opts:["a double coincidence of wants","liquidity","fractional reserves","a unit of account"],exp:"Barter needs two people who each want what the other has. Money removes the need for this match."},
{id:"ep-m27",cat:"m",q:"Why is a credit card not counted in M1?",opts:["It is a loan that must be repaid with money later","It cannot be used in shops","It is issued by the central bank","It earns interest"],exp:"Using a credit card borrows funds. Payment is made later with money."},
{id:"ep-m28",cat:"m",q:"Paying with a debit card is best described as",opts:["transferring funds from a checkable deposit","taking out a loan","creating new fiat money","using commodity money"],exp:"A debit card moves money you already have in a checkable deposit, which is part of M1."},
{id:"ep-m29",cat:"m",q:"Currency 200, checkable deposits 600, savings deposits 1,400 and small time deposits 800 (billion). M1 and M2 are",opts:["M1 = 800; M2 = 3,000","M1 = 800; M2 = 2,200","M1 = 2,200; M2 = 3,000","M1 = 600; M2 = 3,000"],exp:"M1 = 200 + 600 = 800. M2 = M1 + savings + small time deposits = 800 + 1,400 + 800 = 3,000.\n2,200 = leaves out time deposits"},
{id:"ep-m30",cat:"m",q:"The required reserve ratio is 25%. The simple money multiplier is",opts:["4","25","0.25","5"],exp:"Money multiplier = 1 / rr = 1 / 0.25 = 4."},
{id:"ep-m31",cat:"m",q:"A bank receives new reserves of 2,000 and the reserve ratio is 20%. The maximum increase in total deposits in the banking system is",opts:["10,000","8,000","2,000","400"],exp:"Multiplier = 1 / 0.2 = 5, so 2,000 x 5 = 10,000.\n8,000 = counts only the new loans · 400 = the required reserves"},
{id:"ep-m32",cat:"m",q:"A bank has deposits of 800,000, reserves of 200,000 and a 10% reserve requirement. Its excess reserves are",opts:["120,000","80,000","200,000","720,000"],exp:"Required reserves = 10% x 800,000 = 80,000. Excess = 200,000 - 80,000 = 120,000."},
{id:"ep-m33",cat:"m",q:"Why can the banking system as a whole expand deposits by more than a single bank can?",opts:["Loans made by one bank become deposits at other banks","Banks can print currency","Reserves are not required","The central bank guarantees every loan"],exp:"Each loan is redeposited somewhere in the system, and that bank lends part of it again."},
{id:"ep-m34",cat:"m",q:"A customer deposits 1,000 in cash and the reserve ratio is 10%. The bank's excess reserves rise by",opts:["900","1,000","100","0"],exp:"The bank must hold 10% = 100 as required reserves. The rest, 900, can be lent."},
{id:"ep-m35",cat:"m",q:"Cigarettes used as money in a prison camp are an example of",opts:["commodity money","fiat money","credit money","a debit instrument"],exp:"Commodity money has value in itself, apart from its use as money."},
{id:"ep-m36",cat:"m",q:"Which is most likely to destroy confidence in fiat money?",opts:["Unlimited money printing that leads to hyperinflation","Tight control of the money supply","A stable price level","A strong banking system"],exp:"Fiat money has value only because people trust it. Rapid price increases erode that trust."},
{id:"ep-m37",cat:"m",q:"Which asset is the most liquid?",opts:["Cash","A house","A car","Land"],exp:"Liquidity is how quickly and cheaply an asset can be turned into spending power. Cash is already spendable."},
{id:"ep-m38",cat:"m",q:"Banks act as financial intermediaries because they",opts:["channel savings from depositors to borrowers","print currency for households","set the policy interest rate","control the money supply by decree"],exp:"Banks collect deposits and lend them out, connecting savers with borrowers."},
{id:"ep-m39",cat:"m",q:"Why do banks hold only a fraction of deposits as reserves?",opts:["Depositors rarely withdraw all their money at the same time","The law forbids holding cash","Reserves earn high interest","Banks want to avoid making loans"],exp:"Because withdrawals are small and spread out, most funds can be lent to earn interest."},
{id:"ep-m40",cat:"m",q:"A bank makes a 500 loan by crediting the borrower's checking account. Immediately, the bank's balance sheet shows",opts:["loans (assets) and deposits (liabilities) both up by 500","reserves up by 500","deposits down by 500","no change"],exp:"The loan is a new asset and the borrower's new deposit is a new liability. The money supply rises."},
{id:"ep-m41",cat:"m",q:"If borrowers keep part of their loans in cash instead of depositing them, the actual money multiplier is",opts:["smaller than 1 / rr","larger than 1 / rr","equal to zero","unaffected"],exp:"Cash held outside banks cannot be lent again, so deposit expansion is smaller."},
{id:"ep-m42",cat:"m",q:"The money supply falls when",opts:["borrowers repay their bank loans","banks make new loans","the central bank buys bonds","people deposit cash in banks"],exp:"Repaying a loan destroys the deposit that was created when the loan was made."},
{id:"ep-m43",cat:"m",q:"M = 500, V = 4 and P = 2 in the equation MV = PY. Real output Y equals",opts:["1,000","250","4,000","2,000"],exp:"MV = 500 x 4 = 2,000 = P x Y, so Y = 2,000 / 2 = 1,000.\n2,000 = the value of PY, not Y"},
{id:"ep-m44",cat:"m",q:"According to the quantity theory, if the money supply doubles while V and Y stay constant, the price level",opts:["doubles","halves","stays the same","rises by 10%"],exp:"In MV = PY, with V and Y fixed, P rises in proportion to M."},
{id:"ep-m45",cat:"m",q:"A person moves 5,000 from a checking account to a savings account. Then",opts:["M1 falls and M2 does not change","M1 and M2 both fall","M1 and M2 both rise","M1 rises and M2 does not change"],exp:"Checking deposits are in M1, but savings deposits are only in M2. M2 includes both, so it is unchanged."},
{id:"ep-f24",cat:"f",q:"The marginal propensity to consume is 0.6. The simple spending multiplier is",opts:["2.5","1.67","1.5","0.4"],exp:"Multiplier = 1 / (1 - MPC) = 1 / 0.4 = 2.5.\n1.67 = 1 / MPC · 1.5 = MPC / (1 - MPC)"},
{id:"ep-f25",cat:"f",q:"The marginal propensity to consume is 0.6. The tax multiplier is",opts:["-1.5","1.5","-2.5","-0.4"],exp:"Tax multiplier = -MPC / (1 - MPC) = -0.6 / 0.4 = -1.5."},
{id:"ep-f26",cat:"f",q:"MPC = 0.6. Government spending rises by 30 billion. Aggregate demand rises by up to",opts:["75 billion","50 billion","45 billion","30 billion"],exp:"30 x 2.5 = 75.\n50 = used 1 / MPC · 45 = used the tax multiplier"},
{id:"ep-f27",cat:"f",q:"MPC = 0.75. Taxes are cut by 20 billion. Aggregate demand rises by up to",opts:["60 billion","80 billion","20 billion","15 billion"],exp:"Tax multiplier = -0.75 / 0.25 = -3, so a 20 billion tax cut raises AD by 60.\n80 = used the spending multiplier · 15 = the first-round spending"},
{id:"ep-f28",cat:"f",q:"Real GDP is 40 billion below full employment (Keynesian range) and MPC = 0.8. To close the gap by cutting taxes, taxes should be cut by",opts:["10 billion","8 billion","40 billion","50 billion"],exp:"Tax multiplier = -4, so the tax cut needed is 40 / 4 = 10.\n8 = used the spending multiplier"},
{id:"ep-f29",cat:"f",q:"MPC = 0.6. Government spending and taxes both rise by 50 billion. Aggregate demand rises by about",opts:["50 billion","0","75 billion","125 billion"],exp:"Balanced-budget multiplier = 1: 50 x 2.5 = 125 from G, minus 50 x 1.5 = 75 from taxes, which is +50."},
{id:"ep-f30",cat:"f",q:"Government spending is 900 and tax revenue is 840. The budget has",opts:["a deficit of 60","a surplus of 60","a deficit of 1,740","a balance of zero"],exp:"Deficit = spending - revenue = 900 - 840 = 60."},
{id:"ep-f31",cat:"f",q:"A government begins with no debt and runs a deficit of 40 in each of three years. Public debt after three years is",opts:["120","40","13.3","360"],exp:"Debt is the accumulation of deficits: 40 x 3 = 120."},
{id:"ep-f32",cat:"f",q:"In an economic boom, progressive income taxes",opts:["raise tax revenue automatically and dampen spending","lower tax revenue","raise government transfer payments","have no effect"],exp:"As incomes rise, people move into higher tax brackets, so taxes rise faster than income and cool demand."},
{id:"ep-f33",cat:"f",q:"Which is an example of discretionary fiscal policy?",opts:["Parliament passes a one-time stimulus package","Unemployment benefits rise automatically in a recession","Tax revenue falls automatically in a recession","Progressive taxes collect more in a boom"],exp:"Discretionary policy needs a deliberate decision, unlike automatic stabilizers."},
{id:"ep-f34",cat:"f",q:"The recognition lag in fiscal policy is the time it takes",opts:["to realise the economy has a problem","for a law to be passed","for spending to affect output","for banks to lend"],exp:"Data arrive late, so policymakers may not see a recession or boom quickly."},
{id:"ep-f35",cat:"f",q:"The Laffer curve idea says that beyond some tax rate, raising rates may",opts:["reduce total tax revenue","raise tax revenue without limit","raise government spending automatically","increase output"],exp:"Very high rates discourage work and investment and shrink the tax base."},
{id:"ep-f36",cat:"f",q:"To fight demand-pull inflation, fiscal policy should",opts:["cut government spending or raise taxes","raise government spending","cut taxes","increase transfer payments"],exp:"Contractionary fiscal policy reduces aggregate demand."},
{id:"ep-f37",cat:"f",q:"In the intermediate range of AS, expansionary fiscal policy raises",opts:["both the price level and real GDP","real GDP only","the price level only","neither real GDP nor prices"],exp:"In the upward-sloping range AD growth raises output and prices together."},
{id:"ep-f38",cat:"f",q:"A 10 billion increase in transfer payments raises aggregate demand by",opts:["less than a 10 billion increase in government spending","more than a 10 billion increase in government spending","the same as a 10 billion increase in government spending","nothing at all"],exp:"Part of a transfer is saved, so the first-round spending is smaller than with direct government purchases."},
{id:"ep-f39",cat:"f",q:"If the MPC is 0.8, the marginal propensity to save is",opts:["0.2","0.8","1.8","0.25"],exp:"MPS = 1 - MPC = 0.2."},
{id:"ep-f40",cat:"f",q:"A higher MPC makes the spending multiplier",opts:["larger","smaller","unchanged","negative"],exp:"Multiplier = 1 / (1 - MPC). A bigger MPC means more spending is passed on in each round."},
{id:"ep-f41",cat:"f",q:"Why is the tax multiplier smaller in size than the spending multiplier?",opts:["Part of a tax change affects saving instead of spending in the first round","Taxes never change behaviour","Government spending is always taxed","The tax multiplier applies only to firms"],exp:"Households change spending by only MPC times the tax change, so the first round is smaller."},
{id:"ep-f42",cat:"f",q:"Running deficits in recessions and surpluses in booms is called",opts:["countercyclical fiscal policy","procyclical fiscal policy","supply-side policy","a balanced-budget rule"],exp:"The policy leans against the business cycle to stabilize output."},
{id:"ep-f43",cat:"f",q:"Which changes automatically when the economy enters a recession?",opts:["Government spending on unemployment benefits rises","Income tax rates are raised by law","The central bank's reserve requirement changes","Government investment projects are approved"],exp:"Benefits rise as more people become eligible, without any new legislation."},
{id:"ep-n27",cat:"n",q:"The central bank cuts the reserve requirement from 10% to 5%. The simple money multiplier changes from",opts:["10 to 20","10 to 5","20 to 10","5 to 10"],exp:"Multiplier = 1 / rr: 1 / 0.10 = 10, and 1 / 0.05 = 20."},
{id:"ep-n28",cat:"n",q:"The central bank buys 100 million of government bonds and the reserve ratio is 10%. The maximum increase in the money supply is",opts:["1,000 million","100 million","900 million","10,000 million"],exp:"New reserves of 100 million x multiplier 10 = 1,000 million.\n900 = leaves out the original reserves"},
{id:"ep-n29",cat:"n",q:"A central bank raises its policy interest rate to cool an overheating economy. The most likely effect is",opts:["aggregate demand decreases","aggregate demand increases","aggregate supply increases","the money supply rises"],exp:"Higher interest rates reduce borrowing for investment and durable goods."},
{id:"ep-n30",cat:"n",q:"Which is NOT a tool of monetary policy?",opts:["Changing income tax rates","Open-market operations","Changing the reserve requirement","Changing the discount (policy) rate"],exp:"Tax changes are fiscal policy. The other three are central bank tools."},
{id:"ep-n31",cat:"n",q:"Unemployment is high and inflation is low. The central bank should most likely",opts:["lower the policy rate or buy bonds","raise the policy rate","sell bonds","raise the reserve requirement"],exp:"Expansionary policy raises AD to bring down unemployment, and low inflation leaves room for it."},
{id:"ep-n32",cat:"n",q:"In the money market diagram, an increase in the money supply",opts:["lowers the equilibrium interest rate","raises the equilibrium interest rate","shifts money demand to the right","does not change the interest rate"],exp:"The supply curve shifts right and the interest rate falls to balance money demand."},
{id:"ep-n33",cat:"n",q:"A rise in real GDP shifts the demand for money",opts:["to the right, raising the interest rate","to the left, raising the interest rate","to the right, lowering the interest rate","to the left, lowering the interest rate"],exp:"More income means more transactions, so money demand rises."},
{id:"ep-n34",cat:"n",q:"A rise in the price level shifts the demand for money",opts:["to the right","to the left","not at all","along the curve, with no shift"],exp:"Higher prices mean people need more money for the same purchases."},
{id:"ep-n35",cat:"n",q:"The transmission chain of expansionary monetary policy is",opts:["money supply up, interest rate down, investment up, AD up, real GDP up","money supply down, interest rate up, investment down, AD down","money supply up, interest rate up, investment down","interest rate down, AD down, real GDP up"],exp:"Lower rates make borrowing cheaper, which stimulates investment and total demand."},
{id:"ep-n36",cat:"n",q:"If banks hoard excess reserves instead of lending, expansionary monetary policy may",opts:["be less effective","become more effective","raise interest rates","reduce the money supply to zero"],exp:"New reserves do not turn into loans and deposits, so the money multiplier falls."},
{id:"ep-n37",cat:"n",q:"A central bank cuts interest rates. Through the exchange-rate channel, net exports tend to",opts:["rise","fall","become zero","not change"],exp:"Lower rates lead to a weaker currency, which makes exports cheaper and imports dearer."},
{id:"ep-n38",cat:"n",q:"The real interest rate the central bank wants is 2% and expected inflation rises from 3% to 5%. The nominal rate should",opts:["rise from 5% to 7%","fall from 5% to 3%","stay at 5%","rise from 5% to 10%"],exp:"Nominal rate = real rate + expected inflation (Fisher effect): 2% + 5% = 7%."},
{id:"ep-n39",cat:"n",q:"Why are central banks often made independent of elected officials?",opts:["To avoid pressure to create money for short-term political gain","To allow the government to print money","To lower the reserve ratio to zero","To set tax rates"],exp:"Independence helps the bank commit to low inflation."},
{id:"ep-n40",cat:"n",q:"The two main goals of monetary policy are",opts:["stable prices and high employment (output growth)","a budget surplus and low taxes","a fixed exchange rate and low debt","high inflation and low interest rates"],exp:"Central banks aim at price stability and full employment."},
{id:"ep-n41",cat:"n",q:"A supply shock causes stagflation. Why is it hard for the central bank to respond?",opts:["Easing would worsen inflation, and tightening would worsen unemployment","Both inflation and unemployment fall automatically","It has no tools","The AD curve is vertical"],exp:"Policy that helps one problem aggravates the other."},
{id:"ep-n42",cat:"n",q:"The money supply grows 8% a year, real GDP grows 3% and velocity is constant. Inflation is about",opts:["5%","8%","3%","11%"],exp:"%dM + %dV = %dP + %dY gives %dP = 8% - 3% = 5%."},
{id:"ep-n43",cat:"n",q:"Which action is contractionary monetary policy?",opts:["Raising the discount rate","Buying bonds in the open market","Lowering the reserve requirement","Cutting the policy rate"],exp:"A higher discount rate makes borrowing reserves costly, which reduces lending and the money supply."},
{id:"ep-n44",cat:"n",q:"When the central bank buys bonds on the open market, bond prices tend to",opts:["rise, and interest rates fall","fall, and interest rates rise","not change","fall, and interest rates fall"],exp:"More demand for bonds raises their price, and a higher price means a lower yield."},
{id:"ep-n45",cat:"n",q:"Which tool changes the money multiplier rather than the quantity of reserves?",opts:["Changing the reserve requirement","Open-market purchases","Open-market sales","Lending reserves to banks"],exp:"The reserve requirement sets how much of each deposit banks must hold, which determines expansion."},
{id:"ep-n46",cat:"n",q:"The tool of monetary policy used most often in practice is",opts:["open-market operations","changing the reserve requirement","changing income taxes","direct price controls"],exp:"Buying and selling securities is flexible and can be done daily in small amounts."}
];
